SELECT MAX(CASE WHEN RNP = 'normal' AND `T-CRE` < 1.5 THEN `RNP` ELSE NULL END) AS MaxAntiRNP
FROM Laboratory
WHERE `RNP` IS NOT NULL AND `T-CRE` IS NOT NULL;

SELECT COUNT(*) 
FROM Patient 
WHERE SEX = 'F' AND Admission LIKE '+%' AND `First Date` BETWEEN '1998-01-01' AND '1998-12-31';

SELECT 'F' AS `SEX`, COUNT(*) AS `COUNT` FROM Patient WHERE ID IN (SELECT ID FROM Laboratory) AND SEX = 'F'
UNION ALL
SELECT 'M' AS `SEX`, COUNT(*) AS `COUNT` FROM Patient WHERE ID IN (SELECT ID FROM Laboratory) AND SEX = 'M';

SELECT ROUND(AVG(`aCL IgM`), 2) 
FROM Examination 
WHERE Diagnosis LIKE '%SJS%' AND `aCL IgM` > 0;
